mapper.select:
SELECT * FROM ( SELECT ss.* FROM ( SELECT s.* FROM ( SELECT '${otherEffectFlag_01}' otherEffectFlag, CASE WHEN BO.IS_WIN = 'Y' THEN '04' WHEN BO.IS_WIN = 'N' THEN '03' ELSE '02' END isWin, BO.BID_ID bidId, BO.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, FPI.TENDER_TARGET tenderTarget, FPI.TENDER_SDATE bidDateStart, FPI.TENDER_EDATE bidDateEnd, BOBP.ENTRUST_NUM/100 bidPrinAmt, BO.WIN_PRIN_AMT/10000 totalBiddingNum, BOBP.BID_PRICE bidPrice, BO.BID_MODLE bidModle, BO.PAY_TYPE payType, BO.BID_DATE bidCfmDate, FP.TRADE_MARKET tradeMarket, BO.COUNTER_ID counterId, MCP.COUNTER_NAME counterName, BO.REMARK remark FROM BID_ORDER BO LEFT JOIN FIN_PRODUCT FP ON BO.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN ( SELECT BOBP.BID_ID,wm_concat(decode(FPI.TENDER_TARGET,'01',to_char(BID_PRICE*100,'fm999999990.9990')||'%','02',to_char(BID_PRICE,'fm999999990.9990')||'元','03',to_char(BID_PRICE*10000,'fm999999990.90')||'BP')) BID_PRICE,SUM(EE.ENTRUST_NUM) ENTRUST_NUM from BID_ORDER_BID_PRICE BOBP LEFT JOIN ETR_ENTRUST EE ON BOBP.ENTRUST_ID = EE.ENTRUST_ID LEFT JOIN BID_ORDER BO ON BOBP.BID_ID = BO.BID_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = BO.FINPROD_ID group by BOBP.BID_ID ) BOBP ON BO.BID_ID = BOBP.BID_ID LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = BO.COUNTER_ID WHERE FPI.ISSUE_CLASS = '02' AND BO.BID_MODLE !='03' AND BO.IS_CANCEL = 'N' AND BO.BID_ID not in (select B_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL where TG_BUSI_TYPE =#{COMMON_BUSINESS_TYPE_TRD97} and TRADE_STATUS=#{TRADE_STATUS_01} and IS_CANCEL='N')
AND BO.OUR_TRADER = #{userId}
AND FP.FINPROD_MARKET_ID IN
#{item}
AND FP.TRADE_MARKET IN
#{item}
AND FPI.TENDER_TARGET in
#{item}
AND BO.WIN_TYPE in
#{item}
AND FPI.TENDER_SDATE >= TO_DATE(#{bidDateStart},'YYYY-MM-DD') AND FPI.TENDER_EDATE >= TO_DATE(#{bidDateStart},'YYYY-MM-DD')
AND FPI.TENDER_SDATE <= TO_DATE(#{bidDateEnd},'YYYY-MM-DD') AND FPI.TENDER_EDATE <= TO_DATE(#{bidDateEnd},'YYYY-MM-DD')
AND BO.BID_DATE >= TO_DATE(#{bidCfmDateStart},'YYYY-MM-DD')
AND BO.BID_DATE <= TO_DATE(#{bidCfmDateEnd},'YYYY-MM-DD')
AND BO.PAY_TYPE in
#{item}
AND BO.COUNTER_ID in
#{item}
AND BO.COUNTER_ID in
#{item}
AND BO.BID_ID like '%' || #{bidId} || '%'
) s WHERE 1=1
AND s.isWin in
#{item}
) ss left join SYS_DATADICT_LIST sdl_isWin on ss.isWin=sdl_isWin.ITEM_CODE and sdl_isWin.DICT_CODE='FIRST_BID_STATUS' left join SYS_DATADICT_LIST sdl_tp on ss.tradeMarket=sdl_tp.ITEM_CODE and sdl_tp.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST sdl_otherEffectFlag on ss.otherEffectFlag=sdl_otherEffectFlag.ITEM_CODE and sdl_otherEffectFlag.DICT_CODE='STATUS_VALID' left join SYS_DATADICT_LIST sdl_tt on ss.tenderTarget=sdl_tt.ITEM_CODE and sdl_tt.DICT_CODE='TENDER_TARGET' left join SYS_DATADICT_LIST sdl_wt on ss.bidModle=sdl_wt.ITEM_CODE and sdl_wt.DICT_CODE='WIN_TYPE' left join SYS_DATADICT_LIST sdl_ept on ss.payType=sdl_ept.ITEM_CODE and sdl_ept.DICT_CODE='ETR_PAY_TYPE'
)
order by ${sort} ${direction}

if.where:
( sdl_otherEffectFlag.ITEM_VALUE || '|' || sdl_isWin.ITEM_VALUE || '|' || ss.finprodAbbr || '|' || ss.finprodMarketId || '|'
                || '|' || ss.bidId || '|' || sdl_tp.ITEM_VALUE || '|' || sdl_tt.ITEM_VALUE || '|' || sdl_wt.ITEM_VALUE
                || '|' || sdl_ept.ITEM_VALUE || '|' || ss.bidPrice || '|' || ss.counterName
                || '|' || ss.remark
                like '%' || #{search} || '%'
                or to_char(ss.bidPrinAmt)=#{search}
                or to_char(ss.totalBiddingNum)=#{search}
                or to_char(ss.bidDateStart,'YYYY-MM-DD')=#{search}
                or to_char(ss.bidDateEnd,'YYYY-MM-DD')=#{search}
                or to_char(ss.bidDateStart,'YYYY-MM-DD')||'-'||to_char(ss.bidDateEnd,'YYYY-MM-DD')=#{search}
                or to_char(ss.bidCfmDate,'YYYY-MM-DD')=#{search}
                )

mapper.select:
SELECT * FROM ( SELECT ss.* FROM ( SELECT BRT.TOTAL_WIN_ID totalWinId, BRT.STATUS status, CASE WHEN BRT.IS_WIN = 'N' THEN '03' WHEN BRT.IS_WIN = 'Y' THEN '04' ELSE '02' END isWin, BO.BID_ID bidId, BRT.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, FPI.TENDER_TARGET tenderTarget, FPI.TENDER_SDATE bidDateStart, FPI.TENDER_EDATE bidDateEnd, BO.WIN_PRIN_AMT/10000 totalBiddingNum, BOBP.BID_PRICE bidPrice, BO.WIN_TYPE winType, BO.BID_MODLE bidModle, BO.PAY_TYPE payType, BRT.WIN_TYPE bidType, BRT.WIN_PRINAMT/10000 winPrinamt, BRT.WIN_PRICE winPrice, decode(FPI.TENDER_TARGET,'01',to_char(BRT.WIN_PRICE*100,'fm999999990.9990')||'%','02',to_char(BRT.WIN_PRICE,'fm999999990.9990')||'元','03',to_char(BRT.WIN_PRICE*10000,'fm999999990.90')||'BP') winPriceStr, BRD.PAY_AMT payAmt, BRT.SETT_FEE_AMT settFeeAmt, BRT.PAY_DATE payDate, BRT.CREDITOR_DEBT_DATE creditorDebtDate, FPA.LISTING_DATE listingDate, BRT.WIN_DATE winDate, TFPDT.TRADE_DATE tradeDate, FP.TRADE_MARKET tradeMarket, BRT.COUNTER_ID counterId, MCP.COUNTER_NAME counterName, BRT.REMARK remark FROM BID_ORDER BO INNER JOIN (SELECT * FROM (SELECT BRT.* ,ROW_NUMBER() OVER(PARTITION BY BRT.BID_ID ORDER BY BRT.WIN_DATE DESC) RANK FROM BID_RESULT_TOTAL BRT ) WHERE RANK=1 ) BRT ON BO.BID_ID = BRT.BID_ID LEFT JOIN FIN_PRODUCT FP ON BRT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON FP.FINPROD_ID = FPA.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = BRT.COUNTER_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN ( SELECT BOBP.BID_ID,wm_concat(decode(FPI.TENDER_TARGET,'01',to_char(BID_PRICE*100,'fm999999990.9990')||'%','02',to_char(BID_PRICE,'fm999999990.9990')||'元','03',to_char(BID_PRICE*10000,'fm999999990.90')||'BP')) BID_PRICE,SUM(EE.ENTRUST_NUM) ENTRUST_NUM from BID_ORDER_BID_PRICE BOBP LEFT JOIN ETR_ENTRUST EE ON BOBP.ENTRUST_ID = EE.ENTRUST_ID LEFT JOIN BID_ORDER BO ON BOBP.BID_ID = BO.BID_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = BO.FINPROD_ID group by BOBP.BID_ID ) BOBP ON BO.BID_ID = BOBP.BID_ID LEFT JOIN (SELECT TFPDT.B_TRADE_ID, SUM(TFPDT.SHARE_AMT) SHARE_AMT,MAX(TFPDT.TRADE_DATE) TRADE_DATE FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT GROUP BY B_TRADE_ID )TFPDT ON BO.BID_ID = TFPDT.B_TRADE_ID AND TFPDT.SHARE_AMT = BRT.WIN_PRINAMT LEFT JOIN ( SELECT TOTAL_WIN_ID,SUM(BRD.PAY_AMT) PAY_AMT from BID_RESULT_DETAIL BRD group by TOTAL_WIN_ID ) BRD ON BRD.TOTAL_WIN_ID = BRT.TOTAL_WIN_ID WHERE 1=1
AND FP.FINPROD_MARKET_ID IN
#{item}
AND FP.TRADE_MARKET IN
#{item}
AND FPI.TENDER_TARGET in
#{item}
AND BO.WIN_TYPE in
#{item}
AND BO.BID_DATE >= TO_DATE(#{bidDateStart},'YYYY-MM-DD')
AND BO.BID_DATE <= TO_DATE(#{bidDateEnd},'YYYY-MM-DD')
AND BRT.WIN_DATE >= TO_DATE(#{winDateStart},'YYYY-MM-DD')
AND BRT.WIN_DATE <= TO_DATE(#{winDateEnd},'YYYY-MM-DD')
AND BRT.PAY_DATE >= TO_DATE(#{payDateStart},'YYYY-MM-DD')
AND BRT.PAY_DATE <= TO_DATE(#{payDateEnd},'YYYY-MM-DD')
AND FPA.LISTING_DATE >= TO_DATE(#{listingDateStart},'YYYY-MM-DD')
AND FPA.LISTING_DATE <= TO_DATE(#{listingDateEnd},'YYYY-MM-DD')
AND BO.PAY_TYPE in
#{item}
AND BRT.WIN_TYPE in
#{item}
AND BO.BID_ID = #{bidId}
AND (CASE WHEN BO.IS_WIN = 'Y' THEN '04' WHEN BO.IS_WIN = 'N' THEN '03' ELSE '02' END) IN
#{item}
) ss left join SYS_DATADICT_LIST sdl_status on ss.status=sdl_status.ITEM_CODE and sdl_status.DICT_CODE='STATUS_VALID' left join SYS_DATADICT_LIST sdl_tp on ss.tradeMarket=sdl_tp.ITEM_CODE and sdl_tp.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST sdl_tt on ss.tenderTarget=sdl_tt.ITEM_CODE and sdl_tt.DICT_CODE='TENDER_TARGET' left join SYS_DATADICT_LIST sdl_wt on ss.winType=sdl_wt.ITEM_CODE and sdl_wt.DICT_CODE='WIN_TYPE' left join SYS_DATADICT_LIST sdl_ept on ss.payType=sdl_ept.ITEM_CODE and sdl_ept.DICT_CODE='ETR_PAY_TYPE' left join SYS_DATADICT_LIST sdl_bt on ss.bidType=sdl_bt.ITEM_CODE and sdl_bt.DICT_CODE='BID_TYPE'
)
order by ${sort} ${direction}

if.where:
( sdl_status.ITEM_VALUE || '|' || ss.isWin || '|' || ss.finprodAbbr || '|' || ss.finprodMarketId || '|'
                || '|' || ss.bidId || '|' || sdl_tp.ITEM_VALUE || '|' || sdl_tt.ITEM_VALUE || '|' || sdl_wt.ITEM_VALUE
                || '|' || sdl_ept.ITEM_VALUE ||'|' || sdl_bt.ITEM_VALUE || '|' || ss.bidPrice || '|' || ss.winPrice
                || '|' || ss.remark  like '%' || #{search} || '%'
                or to_char(ss.winPrinamt)=#{search}
                or to_char(ss.payAmt)=#{search}
                or to_char(ss.settFeeAmt)=#{search}
                or to_char(ss.totalBiddingNum)=#{search}
                or to_char(ss.bidDateStart,'YYYY-MM-DD')||'-'||to_char(ss.bidDateEnd,'YYYY-MM-DD')=#{search}
                or to_char(ss.payDate,'YYYY-MM-DD')=#{search}
                or to_char(ss.creditorDebtDate,'YYYY-MM-DD')=#{search}
                or to_char(ss.listingDate,'YYYY-MM-DD')=#{search}
                or to_char(ss.winDate,'YYYY-MM-DD')=#{search}
                or to_char(ss.tradeDate,'YYYY-MM-DD')=#{search}
                )

mapper.select:
SELECT BRT.TOTAL_WIN_ID totalWinId, BRT.STATUS status, CASE WHEN BRT.IS_WIN = 'N' THEN '03' WHEN BRT.IS_WIN = 'Y' THEN '04' ELSE '02' END isWin, BO.BID_ID bidId, BRT.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, FPI.TENDER_TARGET tenderTarget, FPI.TENDER_SDATE bidDateStart, FPI.TENDER_EDATE bidDateEnd, BO.WIN_PRIN_AMT/10000 totalBiddingNum, BOBP.BID_PRICE bidPrice, BO.WIN_TYPE winType, BO.BID_MODLE bidModle, BO.PAY_TYPE payType, BRT.WIN_TYPE bidType, BRT.WIN_PRINAMT/10000 winPrinamt, BRT.WIN_PRICE winPrice, decode(FPI.TENDER_TARGET,'01',to_char(BRT.WIN_PRICE*100,'fm999999990.9990')||'%','02',to_char(BRT.WIN_PRICE,'fm999999990.9990')||'元','03',to_char(BRT.WIN_PRICE*10000,'fm999999990.90')||'BP') winPriceStr, BRD.PAY_AMT payAmt, BRT.SETT_FEE_AMT settFeeAmt, BRT.PAY_DATE payDate, BRT.CREDITOR_DEBT_DATE creditorDebtDate, FPA.LISTING_DATE listingDate, BRT.WIN_DATE winDate, TFPDT.TRADE_DATE tradeDate, FP.TRADE_MARKET tradeMarket, BRT.COUNTER_ID counterId, MCP.COUNTER_NAME counterName, BRT.REMARK remark FROM BID_RESULT_TOTAL BRT LEFT JOIN BID_ORDER BO ON BO.BID_ID = BRT.BID_ID LEFT JOIN FIN_PRODUCT FP ON BRT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON FP.FINPROD_ID = FPA.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = BRT.COUNTER_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN ( SELECT BOBP.BID_ID,wm_concat(decode(FPI.TENDER_TARGET,'01',to_char(BID_PRICE*100,'fm999999990.9990')||'%','02',to_char(BID_PRICE,'fm999999990.9990')||'元','03',to_char(BID_PRICE*10000,'fm999999990.90')||'BP')) BID_PRICE,SUM(EE.ENTRUST_NUM) ENTRUST_NUM from BID_ORDER_BID_PRICE BOBP LEFT JOIN ETR_ENTRUST EE ON BOBP.ENTRUST_ID = EE.ENTRUST_ID LEFT JOIN BID_ORDER BO ON BOBP.BID_ID = BO.BID_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = BO.FINPROD_ID group by BOBP.BID_ID ) BOBP ON BO.BID_ID = BOBP.BID_ID LEFT JOIN (SELECT TFPDT.B_TRADE_ID, SUM(TFPDT.SHARE_AMT) SHARE_AMT,MAX(TFPDT.TRADE_DATE) TRADE_DATE FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT GROUP BY B_TRADE_ID )TFPDT ON BO.BID_ID = TFPDT.B_TRADE_ID LEFT JOIN ( SELECT TOTAL_WIN_ID,SUM(BRD.PAY_AMT) PAY_AMT from BID_RESULT_DETAIL BRD group by TOTAL_WIN_ID ) BRD ON BRD.TOTAL_WIN_ID = BRT.TOTAL_WIN_ID WHERE 1=1
AND BO.BID_ID = #{bidId}
UNION ALL SELECT BRT.TOTAL_WIN_ID totalWinId, BRT.STATUS status, CASE WHEN BRT.IS_WIN = 'N' THEN '03' WHEN BRT.IS_WIN = 'Y' THEN '04' ELSE '02' END isWin, BO.BID_ID bidId, BRT.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, FPI.TENDER_TARGET tenderTarget, FPI.TENDER_SDATE bidDateStart, FPI.TENDER_EDATE bidDateEnd, BO.WIN_PRIN_AMT/10000 totalBiddingNum, BOBP.BID_PRICE bidPrice, BO.WIN_TYPE winType, BO.BID_MODLE bidModle, BO.PAY_TYPE payType, BRT.WIN_TYPE bidType, BRT.WIN_PRINAMT/10000 winPrinamt, BRT.WIN_PRICE winPrice, decode(FPI.TENDER_TARGET,'01',to_char(BRT.WIN_PRICE*100,'fm999999990.9990')||'%','02',to_char(BRT.WIN_PRICE,'fm999999990.9990')||'元','03',to_char(BRT.WIN_PRICE*10000,'fm999999990.90')||'BP') winPriceStr, BRD.PAY_AMT payAmt, BRT.SETT_FEE_AMT settFeeAmt, BRT.PAY_DATE payDate, BRT.CREDITOR_DEBT_DATE creditorDebtDate, FPA.LISTING_DATE listingDate, BRT.WIN_DATE winDate, TFPDT.TRADE_DATE tradeDate, FP.TRADE_MARKET tradeMarket, BO.COUNTER_ID counterId, MCP.COUNTER_NAME counterName, BRT.REMARK remark FROM WFL_BID_RESULT_TOTAL BRT LEFT JOIN BID_ORDER BO ON BO.BID_ID = BRT.BID_ID LEFT JOIN FIN_PRODUCT FP ON BRT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON FP.FINPROD_ID = FPA.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = BRT.COUNTER_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN ( SELECT BOBP.BID_ID,wm_concat(decode(FPI.TENDER_TARGET,'01',to_char(BID_PRICE*100,'fm999999990.9990')||'%','02',to_char(BID_PRICE,'fm999999990.9990')||'元','03',to_char(BID_PRICE*10000,'fm999999990.90')||'BP')) BID_PRICE,SUM(EE.ENTRUST_NUM) ENTRUST_NUM from BID_ORDER_BID_PRICE BOBP LEFT JOIN ETR_ENTRUST EE ON BOBP.ENTRUST_ID = EE.ENTRUST_ID LEFT JOIN BID_ORDER BO ON BOBP.BID_ID = BO.BID_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = BO.FINPROD_ID group by BOBP.BID_ID ) BOBP ON BO.BID_ID = BOBP.BID_ID LEFT JOIN (SELECT TFPDT.B_TRADE_ID, SUM(TFPDT.SHARE_AMT) SHARE_AMT,MAX(TFPDT.TRADE_DATE) TRADE_DATE FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT GROUP BY B_TRADE_ID )TFPDT ON BO.BID_ID = TFPDT.B_TRADE_ID LEFT JOIN ( SELECT TOTAL_WIN_ID,SUM(BRD.PAY_AMT) PAY_AMT from WFL_BID_RESULT_DETAIL BRD group by TOTAL_WIN_ID ) BRD ON BRD.TOTAL_WIN_ID = BRT.TOTAL_WIN_ID WHERE 1=1
AND BO.BID_ID = #{bidId}

select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


        PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

SELECT DISTINCT B.ACCT_NO as acctNo, B.ACCT_NAME as acctName FROM MST_COUNTER_ACCT A, STL_CAPACCT_INFO B WHERE A.COUNTER_ID = #{counterId}
AND A.ACCT_TYPE = #{acctType}
AND A.ACCT_NO = B.ACCT_NO AND A.IS_OPEN = '01' AND A.CCY = B.CCY
AND A.CCY = #{ccy}


where
FINPROD_ID = #{finprodId}
and FINPROD_TYPE2 = #{finprodType}
order by EFF_DATE

SELECT
100 - NVL(sum(fcp.PRIN_AMT), 0)
FROM
FIN_CASH_PLAN fcp
inner join FIN_CASH_INFO fci
on fcp.CASH_ID = fci.CASH_ID
WHERE
fcp.FINPROD_ID = #{finprodId}

AND fcp.MDATE < #{settleDate}
and fci.CASH_TYPE_1 = #{cashType1}

SELECT TOTLE_TRADE_ID totleTradeId
FROM TRD_FIN_PRODUCT_DEAL_TOTAL
WHERE B_TRADE_ID = #{bTradeId}

select 
from PTL_TRADE
where BUSI_NO = #{tradeId}
